local({
    previous <- options(useFancyQuotes=FALSE)
    on.exit(options(previous))
    cases <- list(.Dim=c(2L,2L), .Tsp=c(1,4,1), .Label=letters[1:4])
    for (name in names(cases)) {
        messages <- character()
        withCallingHandlers(
            do.call(structure, c(list(1:4), setNames(list(cases[[name]]), name))),
            warning=function(w) {
                messages <<- c(messages, conditionMessage(w))
                invokeRestart("muffleWarning")
            })
        stopifnot(length(messages)==1L)
        cat(name, ": ", messages, "\n", sep="")
    }
})
